package com.skyclone.mod.slayer;

import com.google.gson.Gson;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The slayer data ({@code data/slayer/slayers.json}, generated by tools/gen/slayer/gen_slayer.py from the research).
 * Pure: no Bukkit, so the unit tests read the shipped file through it.
 */
public final class SlayerCatalog {

    public String npcName = "Slayer Master";
    public List<Type> types = new ArrayList<>();

    private transient Map<String, Type> byId;

    public static final class Type {
        public String id;
        public String name;
        public String ref;
        public String t5name;
        public String mobWord;
        public String color = "c";
        public String icon = "ROTTEN_FLESH";
        public List<String> entities = new ArrayList<>();
        /** Defeat this type at this tier to unlock; null = always unlocked. */
        public Unlock unlock;
        /** Cumulative XP to reach level i+1. */
        public long[] xp = new long[0];
        public List<String> levelNames = new ArrayList<>();
        public List<Tier> tiers = new ArrayList<>();
        public List<Reward> rewards = new ArrayList<>();
        public List<Ability> abilities = new ArrayList<>();
        public List<LootEntry> loot = new ArrayList<>();
        public List<Mini> minibosses = new ArrayList<>();
        /** Blaze only: Immolate true damage per tier at 100/66/33% HP. */
        public double[][] immolate;
        public Demons demons;

        public int maxLevel() { return xp.length; }
        public int maxTier() { return tiers.size(); }
        public Tier tier(int t) { return t >= 1 && t <= tiers.size() ? tiers.get(t - 1) : null; }
        public String bossName(int tier) { return tier == 5 && t5name != null ? t5name : name; }
        /** "&2Ghoul Horror" */
        public String colored() { return "&" + color + name; }
        public String slayerName() { return mobWord + " Slayer"; }
        /** "Wolves", "Endermen", "Zombies" (quest text said "Wolfs"). */
        public String mobPlural() {
            if (mobWord == null || mobWord.isEmpty()) return "";
            if (mobWord.endsWith("man")) return mobWord.substring(0, mobWord.length() - 3) + "men";
            if (mobWord.endsWith("f")) return mobWord.substring(0, mobWord.length() - 1) + "ves";
            return mobWord + "s";
        }
        public LootEntry lootEntry(String item) {
            for (LootEntry e : loot) if (e.item.equals(item)) return e;
            return null;
        }
        public String levelName(int level) {
            if (level <= 0 || levelNames.isEmpty()) return "Unranked";
            return levelNames.get(Math.min(level, levelNames.size()) - 1);
        }
    }

    public static final class Unlock {
        public String type;
        public int tier;
    }

    public static final class Tier {
        public int tier;
        public String mob;
        public double health;
        public double dps;
        public double trueDps;
        public int level;
        public double cost;
        public double spawnXp;
        public double slayerXp;
        public double combatXp;
        public int bits;
        public double heal;
        /** Requirement key ("skill:combat:15 & slayerkill:enderman:2"), or null. */
        public String requirement;
        public String difficulty;
        public double tokenWeight;
    }

    public static final class Reward {
        public int level;
        public Map<String, Double> stats = new LinkedHashMap<>();
        public List<String> notes = new ArrayList<>();
        public int sbXp;
    }

    public static final class Ability {
        public int tier;
        public String name;
        public String desc;
    }

    public static final class LootEntry {
        public String item;
        /** Per tier (index tier-1). */
        public int[] min = new int[0];
        public int[] max = new int[0];
        /** Displayed per-kill chance in percent at max level, per tier. 100 = guaranteed. */
        public double[] chance = new double[0];
        public int minLevel;
        public boolean token;
        /** Rolled on its own (dyes, the Paragon shard), outside the weighted pool. */
        public boolean independent;
        /**
         * Drops only to LOOTSHARE helpers, never to the summoner (Inferno's Blaze Rod / Glowstone / Magma Cream /
         * Nether Wart distillates, audit C3 2026-10-06). Its chance is its weight in the helper's roll.
         */
        public boolean lootshareOnly;
        /** RNG meter XP needed; 0 = not selectable. */
        public long rng;
        /**
         * A Hunting shard (wave 5): not an item, it goes to the hunting module's Hunting Box through
         * {@code Features.Hunting.addShards}. {@link #name} / {@link #rarity} are the box's own name and rarity.
         */
        public boolean shard;
        public String name;
        public String rarity;

        public double chanceAt(int tier) { return tier >= 1 && tier <= chance.length ? chance[tier - 1] : 0; }
        public int minAt(int tier) { return tier >= 1 && tier <= min.length ? Math.max(1, min[tier - 1]) : 1; }
        public int maxAt(int tier) { return tier >= 1 && tier <= max.length ? Math.max(minAt(tier), max[tier - 1]) : 1; }
        public boolean dropsAt(int tier) { return chanceAt(tier) > 0; }
        public int highestTier() {
            for (int t = chance.length; t >= 1; t--) if (chance[t - 1] > 0) return t;
            return 0;
        }
    }

    public static final class Mini {
        public String mob;
        public String type;
        public int minTier;
        public double combatXp;
    }

    public static final class Demons {
        public double[] hp = new double[0];
        public double[] dps = new double[0];
    }

    // ---------------------------------------------------------------------------------------

    public Type type(String id) {
        if (byId == null) {
            Map<String, Type> m = new LinkedHashMap<>();
            for (Type t : types) m.put(t.id, t);
            byId = m;
        }
        return id == null ? null : byId.get(id.toLowerCase(java.util.Locale.ROOT));
    }

    public static SlayerCatalog read(Reader r) {
        SlayerCatalog c = new Gson().fromJson(r, SlayerCatalog.class);
        if (c == null) c = new SlayerCatalog();
        return c;
    }

    public static SlayerCatalog read(InputStream in) {
        if (in == null) return new SlayerCatalog();
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            return read(r);
        } catch (java.io.IOException e) {
            throw new IllegalStateException("slayers.json unreadable", e);
        }
    }
}
